def import_monkeycode(log=print):
    sys.path.insert(0, str(runtime_dir() / "monkeycode2openai"))
    mod = importlib.import_module("monkeycode2openai")
    mod.auto_configure(log)
    log("[mc] monkeycode2openai 核心已加载")
    return mod


def import_codearts(log=print):
    sys.path.insert(0, str(runtime_dir() / "codearts2openai"))
    mod = importlib.import_module("codearts2openai")
    log("[ca] codearts2openai 核心已加载")
    return mod


def monkeycode_upstream_base() -> str:
    """探测本机 MonkeyCode 桌面端的 OpenAI 兼容上游 base_url（config.json models[0]）。"""
    app = "com.chaitin.baizhi.monkeycode"
    home = Path.home()
    for base in (
        os.environ.get("APPDATA"),
        home / "AppData" / "Roaming",
        os.environ.get("LOCALAPPDATA"),
        home / "AppData" / "Local",
    ):
        if not base:
            continue
        p = Path(base) / app / "config.json"
        if p.is_file():
            try:
                data = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                continue
            for m in (data.get("models") or []):
                if m.get("api_key") and m.get("base_url"):
                    return m["base_url"]
            return ""
    return ""


