    ttk.Button(hr_row2, text="删除全部反代", width=14,
               command=lambda: threading.Thread(target=remove_from_hermes, daemon=True).start()).pack(side="left", padx=2)
    ttk.Button(hr_row2, text="刷新状态", width=10,
               command=lambda: threading.Thread(target=refresh_hermes_status, daemon=True).start()).pack(side="left", padx=2)

    # ---------------- 日志区 ----------------
    lf = ttk.LabelFrame(root, text=" 运行日志 ", padding=6)
    lf.pack(fill="both", expand=True, padx=10, pady=(6, 4))
    log_text = tk.Text(lf, height=12, font=("Consolas", 9), state="disabled",
                       bg="#111418", fg="#d4d4d4", insertbackground="#fff")
    ys = ttk.Scrollbar(lf, orient="vertical", command=log_text.yview)
    log_text.configure(yscrollcommand=ys.set)
    ys.pack(side="right", fill="y")
    log_text.pack(fill="both", expand=True)
    log_text.tag_configure("err", foreground="#ff6b6b")
    log_text.tag_configure("ok", foreground="#7ee787")

    def _log_copy_selection():
        try:
            sel = log_text.get("sel.first", "sel.last")
        except Exception:
            sel = ""
        if sel:
            root.clipboard_clear()
            root.clipboard_append(sel)

    def _log_select_all():
        try:
            log_text.tag_add("sel", "1.0", "end-1c")
        except Exception:
            pass

    log_menu = tk.Menu(root, tearoff=0)
    log_menu.add_command(label="复制选中", command=_log_copy_selection)
    log_menu.add_command(label="全选", command=_log_select_all)
    log_menu.add_separator()
    log_menu.add_command(label="清空日志", command=lambda: (log_text.configure(state="normal"),
                                                             log_text.delete("1.0", "end"),
                                                             log_text.configure(state="disabled")))

    def _log_popup(event):
        try:
            log_menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                log_menu.grab_release()
            except Exception:
                pass

    log_text.bind("<Button-3>", _log_popup)

    def clear_log():
        log_text.configure(state="normal")
        log_text.delete("1.0", "end")
        log_text.configure(state="disabled")

    def open_logdir():
        logs_dir().mkdir(parents=True, exist_ok=True)
        os.startfile(str(logs_dir()))  # noqa: S606

    lrow = ttk.Frame(lf)
    lrow.pack(fill="x", pady=(4, 0))
    ttk.Button(lrow, text="清空日志", command=clear_log).pack(side="left")
    ttk.Button(lrow, text="打开日志目录", command=open_logdir).pack(side="left", padx=6)

    # ---------------- 行为 ----------------
    def copy_text(t):
        root.clipboard_clear()
        root.clipboard_append(t)
        emit(f"已复制：{t}")

    def _refresh_urls():
        try:
            p = int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787
        except ValueError:
            p = 8787
        host = "127.0.0.1"  # URL 提示固定回环，即便监听 0.0.0.0 也可用
        cb_url.set(f"http://{host}:{p}/v1")
        try:
            p3 = int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000
        except ValueError:
            p3 = 9000
        mc_url.set(f"http://{host}:{p3}/v1")
        try:
            p4 = int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100
        except ValueError:
            p4 = 9100
        ca_url.set(f"http://{host}:{p4}/v1")

    cb_port.bind("<KeyRelease>", lambda e: _refresh_urls())
    mc_port.bind("<KeyRelease>", lambda e: _refresh_urls())
    ca_port.bind("<KeyRelease>", lambda e: _refresh_urls())

    def set_install_path(key: str, path: str):
        def _apply():
            e = {"cb": cb_path, "mc": mc_path}.get(key, ca_path)
            e.delete(0, "end")
            e.insert(0, path)
        ui(_apply)

    def browse_install(key: str):
        from tkinter import filedialog
        p = filedialog.askopenfilename(
                title="选择主程序 exe（取消则可选文件夹）",
                filetypes=[("可执行文件", "*.exe"), ("所有文件", "*.*")])
        if not p:
                p = filedialog.askdirectory(title="或选择安装文件夹（将自动定位其中的 exe）")
        if not p:
                return
        kind = {"cb": "wb", "mc": "mc"}.get(key, "ca")
        resolved = resolve_install_input(p, kind)
        settings[{"cb": "wb_path", "mc": "mc_path"}.get(key, "ca_path")] = resolved
        save_settings(settings)
        set_install_path(key, resolved)
        warn = "" if Path(resolved).exists() else "  ⚠ 路径不存在"
        emit(f"[{key}] 程序位置已设置: {resolved}{warn}")

    def launch_program(key: str):
        """启动程序位置框里的桌面端程序"""
        entry = {"cb": cb_path, "mc": mc_path}.get(key, ca_path)
        p = entry.get().strip()
        if not p:
            emit(f"[{key}] 程序位置为空，先点“浏览…”指定或等自动探测")
            return
        if not Path(p).exists():
            emit(f"[{key}] 路径不存在，无法启动: {p}")
            return
        try:
            os.startfile(p)  # noqa: S606
            emit(f"[{key}] 已启动: {p}")
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 启动失败：{e}")

    # ---------------- 系统托盘 ----------------
    tray_icon = None

    def make_tray_image():
        try:
            from PIL import Image, ImageDraw
            img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
            d = ImageDraw.Draw(img)
            d.rounded_rectangle([4, 4, 60, 60], radius=14, fill=(24, 27, 32, 255))
            d.ellipse([12, 18, 30, 36], fill=(34, 197, 94, 255))    # 绿点：OpenAI 通道
            return img
        except Exception:
            return None

        root.deiconify()
        root.lift()
        try:
            root.focus_force()
        except Exception:
            pass

    def create_tray():
        nonlocal tray_icon
        if tray_icon is not None:
            return
        try:
            import pystray
            img = make_tray_image()
            if img is None:
                emit("[tray] 无法生成托盘图标，关闭窗口将直接退出")
                return
            menu = pystray.Menu(
                pystray.MenuItem("显示主窗口", lambda *a: ui(show_from_tray), default=True),
                pystray.MenuItem("▶ 一键启动", lambda *a: ui(lambda: threading.Thread(target=start_all, daemon=True).start())),
                pystray.MenuItem("■ 全部停止", lambda *a: ui(lambda: threading.Thread(target=stop_all, daemon=True).start())),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem("退出", lambda *a: ui(real_exit)),
            )
            tray_icon = pystray.Icon(APP_NAME, img, f"{APP_NAME} · WorkBuddy/MonkeyCode 反代网关", menu)
            threading.Thread(target=tray_icon.run, daemon=True).start()
            emit("[tray] 系统托盘已启用：点 × 缩小到托盘，服务继续运行")
        except Exception as e:  # noqa: BLE001
            tray_icon = None
            emit(f"[tray] 系统托盘不可用（{e}），关闭窗口将直接退出")

    def _persist():
        settings.update({
            "cb_port": int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787,
            "cb_api_key": cb_key.get().strip(),
            "cb_desensitize": bool(cb_desens.get()),
            "cb_filelog": bool(cb_filelog.get()),
            "mc_port": int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000,
            "mc_api_key": mc_key.get().strip(),
            "mc_path": mc_path.get().strip(),
            "mc_pool_enabled": bool(mc_pool_on.get()),
            "mc_pool": settings.get("mc_pool") or [],
            "ca_port": int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100,
            "ca_api_key": ca_key.get().strip(),
            "allow_lan": bool(lan_var.get()),
            "autostart": bool(autostart_var.get()),
            "hermes_sync_cb": bool(hr_sync_cb.get()),
            "hermes_sync_mc": bool(hr_sync_mc.get()),
            "hermes_sync_ca": bool(hr_sync_ca.get()),
        })
        save_settings(settings)

    def _host() -> str:
        return "0.0.0.0" if lan_var.get() else "127.0.0.1"

    # ---------------- Hermes Agent 集成 ----------------
    def hermes_profile_homes() -> list:
        """本机全部 Hermes profile 目录（默认 + profiles/*，以存在 config.yaml 为准）"""
        homes = []
        cands = [Path.home() / ".hermes",
                 _localappdata() / "hermes"]
        profdir = _localappdata() / "hermes" / "profiles"
        try:
            for sub in sorted(profdir.iterdir()):
                if sub.is_dir():
                    cands.append(sub)
        except OSError:
            pass
        seen = set()
        for h in cands:
            try:
                key = str(h.resolve())
            except OSError:
                key = str(h)
            if key in seen:
                continue
            seen.add(key)
            if (h / "config.yaml").is_file():
                homes.append(h)
        return homes

    def hermes_config_path() -> Path:
        # 活动 profile 优先（桌面端/HERMES_HOME），回退默认 ~/.hermes
        home = os.environ.get("HERMES_HOME", "").strip()
        if home:
            return Path(home) / "config.yaml"
        return Path.home() / ".hermes" / "config.yaml"

    def hermes_env_path(home=None) -> Path:
        base = Path(home) if home else hermes_config_path().parent
        return base / ".env"

    def read_hermes_config(path=None) -> dict | None:
        p = Path(path) if path else hermes_config_path()
        if not p.is_file():
            return None
        try:
            import yaml
            return yaml.safe_load(p.read_text(encoding="utf-8")) or {}
        except Exception as e:
            emit(f"[hermes] 读取配置失败({p}): {e}")
            return None

    def write_hermes_config(cfg: dict, path=None) -> bool:
        p = Path(path) if path else hermes_config_path()
        try:
            import yaml
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(yaml.safe_dump(cfg, allow_unicode=True, sort_keys=False), encoding="utf-8")
            return True
        except Exception as e:
            emit(f"[hermes] 写入配置失败({p}): {e}")
            return False

    def _buddyz_key_env(pid: str) -> str:
        # 与 hermes 官方 custom_endpoint_key_env 同规则
        slug = re.sub(r"[^A-Z0-9]+", "_", pid.upper()).strip("_")
        return f"HERMES_CUSTOM_{slug}_API_KEY" if slug else "HERMES_CUSTOM_API_KEY"

    def _ensure_hermes_env_key(var: str, val: str, home=None):
        """key 写入 profile .env（无查重追加）；对应 hermes 的 key_env 机制"""
        p = hermes_env_path(home)
        try:
            cur = p.read_text(encoding="utf-8") if p.is_file() else ""
            if re.search(rf"(?m)^{re.escape(var)}\s*=", cur):
                return
            if cur and not cur.endswith("\n"):
                cur += "\n"
            cur += f"{var}={val}\n"
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(cur, encoding="utf-8")
        except OSError as e:  # noqa: BLE001
            emit(f"[hermes] 写入 .env 失败: {e}")

    def _buddyz_hermes_entries(host: str, cb_p: int, mc_p: int, ca_p: int) -> dict:
        """providers.<id> 条目（桌面端自定义端点面板认这个 schema）"""
        def _entry(pid: str, port: int, key: str, models: list):
            models = models or ["auto"]
            return {
                "name": pid,
                "base_url": f"http://{host}:{port}/v1",
                "model": models[0],
                "discover_models": True,
                "models": {m: {} for m in models[:12]},
                "key_env": _buddyz_key_env(pid),
            }
        return {
            "buddyz-cb": _entry("buddyz-cb", cb_p, "cb", eff_models("cb")),
            "buddyz-mc": _entry("buddyz-mc", mc_p, "mc", eff_models("mc")),
            "buddyz-ca": _entry("buddyz-ca", ca_p, "ca", eff_models("ca")),
        }

    def sync_to_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置，请确认 Hermes Agent 已安装")
            return
        host = _host()
        cb_p = int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787
        mc_p = int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000
        ca_p = int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100

        # 只同步勾选的 provider
        all_entries = _buddyz_hermes_entries(host, cb_p, mc_p, ca_p)
        selected = {}
        names = []
        if hr_sync_cb.get():
            selected["buddyz-cb"] = all_entries["buddyz-cb"]
            names.append("WorkBuddy")
        if hr_sync_mc.get():
            selected["buddyz-mc"] = all_entries["buddyz-mc"]
            names.append("MonkeyCode")
        if hr_sync_ca.get():
            selected["buddyz-ca"] = all_entries["buddyz-ca"]
            names.append("华为云")
        if not selected:
            emit("[hermes] 未勾选任何反代，请先勾选要同步的服务")
            return

        ok_homes = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            # 先移除所有 buddyz-*，再写入选中的
            for k in [k for k in providers if str(k).startswith("buddyz-")]:
                providers.pop(k, None)
            providers.update(selected)
            cfg["providers"] = providers
            # 占位 key 进各 profile .env（本地反代不校验，hermes 侧要求 key 存在）
            for pid in selected:
                _ensure_hermes_env_key(_buddyz_key_env(pid), "local-noauth", home)
            if write_hermes_config(cfg, home / "config.yaml"):
                ok_homes.append(home.name)
        if ok_homes:
            emit(f"[hermes] 已同步 {len(selected)} 个 provider（{' / '.join(names)}）到 {len(ok_homes)} 个 profile：{', '.join(ok_homes)}")
            hermes_status_label.config(foreground="#28a745")
            hermes_status_var.set(f"已同步（{' / '.join(names)}）×{len(ok_homes)}配置")
            _persist()
        else:
            emit("[hermes] 同步失败")

    def remove_from_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置")
            return
        total = 0
        touched = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            buddyz_keys = [k for k in providers if str(k).startswith("buddyz-")]
            if not buddyz_keys:
                continue
            for k in buddyz_keys:
                providers.pop(k, None)
            cfg["providers"] = providers
            if write_hermes_config(cfg, home / "config.yaml"):
                total += len(buddyz_keys)
                touched.append(home.name)
        if total == 0:
            emit("[hermes] 所有 profile 中均未找到 BuddyZGateway 的 provider")
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")
        else:
            emit(f"[hermes] 已从 {len(touched)} 个 profile 移除 {total} 个 provider（.env 占位 key 保留）：{', '.join(touched)}")
            hermes_status_label.config(foreground="#888")
            hermes_status_var.set("未同步")

    def refresh_hermes_status():
        homes = hermes_profile_homes()
        if not homes:
            hermes_status_var.set("未检测到 Hermes")
            hermes_status_label.config(foreground="#888")
            return
        buddyz_names = []
        name_map = {"buddyz-cb": "WorkBuddy", "buddyz-mc": "MonkeyCode", "buddyz-ca": "华为云"}
        hit_homes = 0
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            found_here = False
            for k in providers:
                if str(k) in name_map:
                    if name_map[str(k)] not in buddyz_names:
                        buddyz_names.append(name_map[str(k)])
                    found_here = True
            if found_here:
                hit_homes += 1
        if buddyz_names:
            hermes_status_var.set(f"已同步（{' / '.join(buddyz_names)}）×{hit_homes}/{len(homes)}配置")
            hermes_status_label.config(foreground="#28a745")
        else:
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")

    def eff_models(key: str) -> list:
        """当前生效的暴露模型列表（空存储 → 默认全集）。"""
        stored = settings.get(f"{key}_models") or []
        if stored:
            return list(stored)
        if key == "cb":
            return list(CB_MODEL_CANDIDATES)
        if key == "ca":
            return list(CA_MODEL_CANDIDATES)
        return list(MC_DEFAULT_MODELS)

    def apply_models_live(key: str, sel: list):
        """把模型选择立即应用到已加载的核心（无需重启服务）。"""
        if key == "cb":
            conv = sys.modules.get("converter")
            if conv is not None:
                conv.CONFIG["exposed_models"] = list(sel)
        elif key == "mc":
            mc = sys.modules.get("monkeycode2openai")
            if mc is not None:
                mc.CONFIG["exposed_models"] = list(sel)
        elif key == "ca":
            ca = sys.modules.get("codearts2openai")
            if ca is not None:
                ca.CONFIG["exposed_models"] = list(sel)

    def refresh_model_hints():
        cb = eff_models("cb")
        mc = eff_models("mc")
        ca = eff_models("ca")
        cb_models_hint.set("模型: " + (", ".join(cb[:4]) + (" …共%d个" % len(cb) if len(cb) > 4 else "") if cb else "全部"))
        mc_models_hint.set("模型: " + (", ".join(mc[:4]) + (" …共%d个" % len(mc) if len(mc) > 4 else "") if mc else "默认"))
        ca_models_hint.set("模型: " + (", ".join(ca) if ca else "默认"))

    def mc_usage_text() -> str:
        """仅服务运行时查询今日用量，静默失败返回空串"""
        try:
            if not services["mc"].running:
                return ""
            import urllib.request
            port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/v1/usage", timeout=3) as r:
                d = json.loads(r.read().decode("utf-8"))
            return (f"今日已用 {d.get('total', 0):,} tokens "
                    f"(prompt {d.get('prompt', 0):,} / completion {d.get('completion', 0):,} · {d.get('requests', 0)}次)")
        except Exception:
            return ""

    def refresh_mc_info():
        """mc_info 多行显示：第1行上游，第2行今日用量，第3行积分，第4行号池"""
        mc = sys.modules.get("monkeycode2openai")
        if mc is not None and mc.CONFIG.get("base_url"):
            line1 = (f"✓ 上游：{mc.CONFIG['base_url']}"
                     f"  ·  key: {(mc.CONFIG.get('api_key') or '')[:6]}…")
            fg = "#1a7f37"
        else:
            base = monkeycode_upstream_base()
            if base:
                line1 = f"✓ 上游已探测：{base}"
                fg = "#1a7f37"
            else:
                line1 = "✗ 未找到上游（config.json 无 models[0].api_key）"
                fg = "#c0392b"
        u = mc_usage_text()
        w = mc_wallet_text()
        p = mc_pool_text()
        extra = "\n".join(x for x in (u, w, p) if x)
        mc_info.configure(text=line1 + (f"\n{extra}" if extra else ""), foreground=fg)

    def mc_pool_text() -> str:
        """号池状态行（仅服务运行时查 /health；关闭时显示配置数）"""
        try:
            ncfg = len(settings.get("mc_pool") or [])
            if not services["mc"].running:
                return f"号池关（已配 {ncfg} 个 key）" if not bool(mc_pool_on.get()) and ncfg else (
                    "" if not ncfg else f"号池开（{ncfg} 个 key，未运行）")
            port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
            d, _ = _http_json(f"http://127.0.0.1:{port}/health", timeout=5)
            pool = (d.get("pool") or {}) if isinstance(d, dict) else {}
            if not pool.get("enabled"):
                return ""
            keys = pool.get("keys") or []
            ok = sum(1 for k in keys if not k.get("cooling") and not k.get("off"))
            return f"号池开·可用 {ok}/{len(keys)}"
        except Exception:
            return ""

    def _http_json(url, timeout=10, method="GET", data=None):
        """GET/POST 取 JSON；HTTPError 时也解析 body（网关 502 的 body 里有真错误信息）"""
        import urllib.request
        import urllib.error
        try:
            req = urllib.request.Request(url, data=data, method=method)
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read().decode("utf-8")), ""
        except urllib.error.HTTPError as e:
            try:
                d = json.loads(e.read().decode("utf-8"))
                return d, str(d.get("error") or d.get("detail") or f"HTTP {e.code}")
            except Exception:
                return {}, f"HTTP {e.code}"
        except Exception as e:  # noqa: BLE001
            return {}, str(e)

    def mc_wallet_text() -> str:
        """仅服务运行时查询 SaaS 钱包积分；会话过期则明示，其余记日志"""
        if not services["mc"].running:
            return ""
        port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
        d, err = _http_json(f"http://127.0.0.1:{port}/v1/wallet", timeout=10)
        if not d.get("ok"):
            err = err or str(d.get("error") or "")
            if "会话" in err or "401" in err or "过期" in err:
                return "积分：会话过期，请打开 MonkeyCode 桌面端登录"
            if err:
                emit(f"[mc] 钱包查询失败：{err}")
            return ""
        w = d.get("data") or {}
        bal = float(w.get("balance") or 0)
        dtb = int(w.get("daily_token_balance") or 0)
        dtl = int(w.get("daily_token_limit") or 0)
        return f"积分 {bal / 1000:.2f}（{bal:,.0f}）· 每日token {dtb:,}/{dtl:,}"

    def mc_checkin():
        """签到：先查状态，未签则 POST 签到"""
        if not services["mc"].running:
            emit("[mc] 未运行，无法签到")
            return
        port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
        base = f"http://127.0.0.1:{port}"
        st, err = _http_json(base + "/v1/checkin", timeout=15)
        if err:
            emit(f"[mc] 签到状态查询失败：{err}")
            return
        if (st.get("data") or {}).get("checked_in"):
            emit("[mc] 今日已签到，无需重复")
            ui(refresh_mc_info)
            return
        res, err = _http_json(base + "/v1/checkin", timeout=120, method="POST", data=b"{}")
        if res.get("ok"):
            emit("[mc] 签到成功（+100 积分）")
        else:
            emit(f"[mc] 签到失败：{err or res.get('error')}")
        ui(refresh_mc_info)

    def _auto_checkin_quiet():
        """启动后自动签到：已签/失败都只记一条日志，不打扰"""
        import time as _t
        _t.sleep(3)
        if not services["mc"].running:
            return
        port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
        base = f"http://127.0.0.1:{port}"
        st, err = _http_json(base + "/v1/checkin", timeout=15)
        if err or (st.get("data") or {}).get("checked_in"):
            return
        res, _ = _http_json(base + "/v1/checkin", timeout=120, method="POST", data=b"{}")
        if res.get("ok"):
            emit("[mc] 自动签到成功（+100 积分）")
            ui(refresh_mc_info)

    def _mc_free_ids() -> set:
        """桌面端 config 里 monkeycode-basic/* 即本机有权用的免费基础模型（去前缀）"""
        try:
            from pathlib import Path as _P
            import os as _os
            home = _P.home()
            for base in (_os.environ.get("APPDATA"), home / "AppData" / "Roaming"):
                if not base:
                    continue
                p = _P(base) / "com.chaitin.baizhi.monkeycode" / "config.json"
                if not p.is_file():
                    continue
                data = json.loads(p.read_text(encoding="utf-8"))
                out = set()
                for m in (data.get("models") or []):
                    mid = m.get("model") or ""
                    if mid.startswith("monkeycode-basic/"):
                        out.add(mid.split("/", 1)[1])
                if out:
                    return out
        except Exception:
            pass
        return set(MC_MODEL_CANDIDATES)

    def _fetch_live_models(key: str) -> list:
        """从运行中的服务拉全量模型 id（mc 带 ?all=1 跳过白名单）；失败返回 []"""
        try:
            import urllib.request
            if key == "mc":
                port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
                url = f"http://127.0.0.1:{port}/v1/models?all=1"
            else:
                url = cb_url.get().rstrip("/") + "/models"
            with urllib.request.urlopen(url, timeout=8) as r:
                d = json.loads(r.read().decode("utf-8"))
            ids = [m.get("id") for m in (d.get("data") or []) if isinstance(m, dict) and m.get("id")]
            stored = settings.get(f"{key}_models") or []
            ids += [m for m in stored if m not in ids]
            return ids
        except Exception:
            return []

    def models_dialog(key: str):
        titles = {"cb": "CodeBuddy → OpenAI", "mc": "MonkeyCode → OpenAI", "ca": "CodeArts → OpenAI"}
        if key == "mc" and services["mc"].running:
            live = _fetch_live_models("mc")
            if live:
                free = _mc_free_ids()
                # 免费基础排前标 ★，其余线上模型在后
                cands = sorted([m for m in live if m in free]) + sorted([m for m in live if m not in free])
                src = f"线上实时（{len(live)}个，★={len([m for m in live if m in free])}个免费基础）"
            else:
                cands = list(MC_MODEL_CANDIDATES)
                src = "内置名单（服务无响应）"
        else:
            cands = {"mc": MC_MODEL_CANDIDATES, "cb": CB_MODEL_CANDIDATES}.get(key, CA_MODEL_CANDIDATES)
            src = "内置名单"
        eff = eff_models(key)
        free = _mc_free_ids() if key == "mc" else set()
        ncol = 3 if len(cands) > 20 else 2
        win = tk.Toplevel(root)
        win.title("选择暴露的模型 · " + titles.get(key, key))
        win.transient(root)
        win.grab_set()
        frm = ttk.Frame(win, padding=14)
        frm.pack(fill="both", expand=True)
        ttk.Label(frm, text=f"勾选要在 /v1/models 中暴露的模型（{src}；★=免费基础可直接用；客户端仍可请求其它模型名，透传不做拦截)：",
                  wraplength=int(420 * scale), justify="left").grid(row=0, column=0, columnspan=ncol, sticky="w")
        vars_map = {}
        for i, m in enumerate(cands):
            v = tk.BooleanVar(value=(m in eff))
            vars_map[m] = v
            label = f"★ {m}" if m in free else m
            ttk.Checkbutton(frm, text=label, variable=v).grid(row=1 + i // ncol, column=i % ncol, sticky="w", padx=8, pady=3)
        row = 1 + (len(cands) + ncol - 1) // ncol
        ttk.Label(frm, text="自定义(逗号分隔):").grid(row=row, column=0, sticky="w", pady=(10, 0))
        custom = ttk.Entry(frm, width=36)
        custom.grid(row=row, column=1, sticky="we", pady=(10, 0))

        def save():
            sel = [m for m in cands if vars_map[m].get()]
            sel += [x.strip() for x in custom.get().split(",") if x.strip()]
            sel = list(dict.fromkeys(sel))
            settings[f"{key}_models"] = sel
            save_settings(settings)
            apply_models_live(key, sel)
            refresh_model_hints()
            emit(f"[{key}] 暴露模型已更新: {', '.join(sel) if sel else '默认'}")
            win.destroy()

        btns = ttk.Frame(frm)
        btns.grid(row=row + 1, column=0, columnspan=ncol, sticky="e", pady=(12, 0))
        ttk.Button(btns, text="取消", command=win.destroy).pack(side="left", padx=4)
        ttk.Button(btns, text="保存", command=save).pack(side="left")

    def pool_dialog():
        """号池管理：key 增删/启用 + 实时状态（key 明文存本地 settings.json）"""
        win = tk.Toplevel(root)
        win.title("MonkeyCode 号池管理")
        win.transient(root)
        win.grab_set()
        frm = ttk.Frame(win, padding=14)
        frm.pack(fill="both", expand=True)
        ttk.Label(frm, text="本机桌面端永远打底；池 key 按顺序轮转，401/429/5xx 自动冷却切换。key 明文保存在本地 settings.json。",
                  wraplength=int(440 * scale), justify="left").pack(anchor="w")
        # 实时状态
        live = {}
        if services["mc"].running:
            try:
                port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
                d, _ = _http_json(f"http://127.0.0.1:{port}/health", timeout=5)
                for k in ((d.get("pool") or {}).get("keys") or []):
                    live[k.get("key_prefix")] = k
            except Exception:
                pass
        lst = tk.Listbox(frm, width=64, height=8, font=("Consolas", 9))
        lst.pack(fill="x", pady=(8, 4))

        def _reload_list():
            lst.delete(0, "end")
            for k in (settings.get("mc_pool") or []):
                st = live.get((k.get("api_key") or "")[:6])
                if st is not None:
                    flag = "OFF" if st.get("off") else ("COOL" if st.get("cooling") else "OK")
                else:
                    flag = "ON" if k.get("enabled", True) else "OFF"
                lst.insert("end", f"[{flag}] {(k.get('label') or '')[:18]:18} {(k.get('base_url') or '')[:34]} key:{(k.get('api_key') or '')[:6]}…")

        _reload_list()
        ttk.Label(frm, text="备注名").pack(anchor="w")
        e_label = ttk.Entry(frm, width=40)
        e_label.pack(fill="x")
        ttk.Label(frm, text="base_url（如 https://ai-models.app.baizhi.cloud/api/openai/v1）").pack(anchor="w")
        e_base = ttk.Entry(frm, width=40)
        e_base.pack(fill="x")
        e_base.insert(0, "https://ai-models.app.baizhi.cloud/api/openai/v1")
        ttk.Label(frm, text="api_key（sk-…，明文存本地）").pack(anchor="w")
        e_key = ttk.Entry(frm, width=40)
        e_key.pack(fill="x")

        def _save_pool():
            settings["mc_pool_enabled"] = bool(mc_pool_on.get())
            save_settings(settings)
            mc = sys.modules.get("monkeycode2openai")
            if mc is not None:
                mc.CONFIG["pool_enabled"] = bool(mc_pool_on.get())
                mc.CONFIG["pool_keys"] = [dict(k) for k in (settings.get("mc_pool") or [])]
            refresh_mc_info()

        def grab_local():
            """从本机桌面端 config.json 抓当前登录号的 key（41 个模型共用一把）"""
            try:
                from pathlib import Path as _P
                p = _P.home() / "AppData" / "Roaming" / "com.chaitin.baizhi.monkeycode" / "config.json"
                data = json.loads(p.read_text(encoding="utf-8"))
                got = [(m.get("base_url", "").rstrip("/"), m.get("api_key", ""))
                       for m in (data.get("models") or [])
                       if m.get("api_key") and m.get("base_url")]
                if not got:
                    emit("[mc-pool] 本机 config.json 里没找到 key（桌面端未登录？）")
                    return
                base, key = got[0]
                for b, k in got:  # 优先 openai 兼容端（网关透传用的就是它）
                    if "openai" in b:
                        base, key = b, k
                        break
                e_base.delete(0, "end")
                e_base.insert(0, base)
                e_key.delete(0, "end")
                e_key.insert(0, key)
                emit(f"[mc-pool] 已抓取本机 key（{key[:6]}…），填好备注名点“添加”")
            except Exception as e:  # noqa: BLE001
                emit(f"[mc-pool] 抓取失败：{e}")

        def add_key():
            base, key, label = e_base.get().strip(), e_key.get().strip(), e_label.get().strip()
            if not base or not key:
                emit("[mc-pool] base_url 和 api_key 都要填")
                return
            pool = settings.get("mc_pool") or []
            if any(k.get("api_key") == key for k in pool):
                emit("[mc-pool] 该 key 已存在")
                return
            pool.append({"base_url": base, "api_key": key, "enabled": True,
                         "label": label or f"号{len(pool) + 1}"})
            settings["mc_pool"] = pool
            _save_pool()
            _reload_list()
            e_label.delete(0, "end")
            e_key.delete(0, "end")
            emit(f"[mc-pool] 已添加（共 {len(pool)} 个）")

        def del_sel():
            sel = lst.curselection()
            if not sel:
                return
            pool = settings.get("mc_pool") or []
            pool.pop(sel[0])
            settings["mc_pool"] = pool
            _save_pool()
            _reload_list()

        def toggle_sel():
            sel = lst.curselection()
            if not sel:
                return
            pool = settings.get("mc_pool") or []
            k = pool[sel[0]]
            k["enabled"] = not k.get("enabled", True)
            _save_pool()
            _reload_list()

        btns = ttk.Frame(frm)
        btns.pack(fill="x", pady=(10, 0))
        ttk.Button(btns, text="抓取本机", command=grab_local).pack(side="left", padx=4)
        ttk.Button(btns, text="添加", command=add_key).pack(side="left", padx=4)
        ttk.Button(btns, text="启用/停用", command=toggle_sel).pack(side="left", padx=4)
        ttk.Button(btns, text="删除选中", command=del_sel).pack(side="left", padx=4)
        ttk.Button(btns, text="关闭", command=win.destroy).pack(side="right", padx=4)

    def ensure_ready() -> bool:
        miss = missing_deps()
        if miss:
            emit(f"[deps] 缺少依赖：{' '.join(miss)}，自动安装…")
            if not install_deps(emit):
                return False
        return True

    def start_cb():
        svc = services["cb"]
        if svc.running:
            emit("[cb] 已在运行")
            return
        if not ensure_ready():
            return
        try:
            port = int(cb_port.get())
        except ValueError:
            emit("[cb] 端口无效"); return
        host = _host()
        if not port_free(host, port):
            _ui_status("cb", "error", f"端口 {port} 被占用")
            return
        emit(f"[cb] 启动中 … http://{host}:{port}")
        try:
            conv = import_converter(emit)
            conv.CONFIG["api_key"] = cb_key.get().strip()
            conv.CONFIG["desensitize"] = bool(cb_desens.get())
            conv.CONFIG["log_path"] = str(logs_dir() / "codebuddy2openai.log") if cb_filelog.get() else None
            af = conv.find_auth_file()
            conv.CONFIG["cred"] = conv.CredentialManager(af) if af else None
            conv.CONFIG["exposed_models"] = eff_models("cb")
            if af is None:
                emit("[cb] ⚠ 未找到登录凭据（请先登录 WorkBuddy/CodeBuddy 桌面端），服务可启动但请求会 503")
            svc.start(conv.app, host, port)
            _persist()
            ui(refresh_cb_credits)
        except Exception as e:  # noqa: BLE001
            emit(f"[cb] 启动失败：{type(e).__name__}: {e}")

    def start_mc():
        svc = services["mc"]
        if svc.running:
            emit("[mc] 已在运行")
            return
        if not ensure_ready():
            return
        try:
            port = int(mc_port.get())
        except ValueError:
            emit("[mc] 端口无效"); return
        host = _host()
        if not port_free(host, port):
            _ui_status("mc", "error", f"端口 {port} 被占用")
            return
        emit(f"[mc] 启动中 … http://{host}:{port}")
        try:
            mc = import_monkeycode(emit)
            mc.CONFIG["local_api_key"] = mc_key.get().strip()
            mc.CONFIG["exposed_models"] = eff_models("mc")
            mc.CONFIG["log_path"] = str(logs_dir() / "monkeycode2openai.log")
            mc.CONFIG["pool_enabled"] = bool(mc_pool_on.get())
            mc.CONFIG["pool_keys"] = [dict(k) for k in (settings.get("mc_pool") or [])]
            if bool(mc_pool_on.get()):
                emit(f"[mc-pool] 号池已开启（{len(mc.CONFIG['pool_keys'])} 个 key + 本机桌面端打底）")
            if mc.CONFIG["base_url"] and mc.CONFIG["api_key"]:
                ui(refresh_mc_info)
            else:
                emit("[mc] ⚠ 未找到上游配置（config.json 中无 models[0].api_key），服务可启动但请求会失败")
            svc.start(mc.app, host, port)
            _persist()
            ui(refresh_mc_info)
            # 启动后顺手自动签到（已签则跳过，静默失败不打扰）
            threading.Thread(target=_auto_checkin_quiet, daemon=True).start()
        except Exception as e:  # noqa: BLE001
            emit(f"[mc] 启动失败：{type(e).__name__}: {e}")

