    def stop_svc(key):
        svc = services[key]
        if not svc.running and svc.thread is None:
            return
        emit(f"[{key}] 正在停止 …")
        try:
            svc.stop()
            emit(f"[{key}] 已停止")
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 停止异常：{e}")

